{
  "name": "nadir-route",
  "description": "Right-size every prompt and every subagent spawn. A UserPromptSubmit hook asks Nadir's free decision API which tier the prompt needs and, when a cheaper tier suffices, gives the agent Nadir's read and a pick from five worker agents (each a fixed model and effort: Haiku; Sonnet at low, medium or high effort; Opus at medium), and the agent decides whether to hand the work off. A PreToolUse hook right-sizes every other spawn, using your harness's own aliases so the pick stays in your model family and generation; a worker the agent picked is left as chosen. Complex work and your main thread's own model are never touched, except read-only Explore searches, which take the rung below (Sonnet under an Opus session), and, unless you turn off the switch_main_model option, a main-thread turn Nadir's cache check prices cheaper on Haiku. Fail-open: any error and the prompt or spawn proceeds exactly as intended.",
  "version": "0.11.0",
  "userConfig": {
    "api_key": {
      "type": "string",
      "title": "Nadir API key",
      "description": "Optional. With a key, every routing decision, the session it belongs to, and the model the turn actually ran are recorded on your account and shown on the Nadir dashboard (Logs). Without one, decisions are anonymous and nothing is stored. Create a key at https://app.getnadir.com/dashboard/api-keys. An NADIR_API_KEY environment variable takes precedence.",
      "sensitive": true,
      "required": false
    },
    "switch_main_model": {
      "type": "boolean",
      "title": "Switch the main model when it saves money",
      "default": true,
      "required": false,
      "description": "On by default; turn it off to keep every turn on your own model. On, the prompt hook gives main-session advice and a hooks module runs a turn's main-thread requests on the cheaper model Nadir suggested, only when its cache check prices the switch below staying on your warm model (a warm session usually stays: re-writing the prompt cache on another model costs more). Shown on the status line and in a toast. Without NADIR_CLAUDE_MODELS or ANTHROPIC_DEFAULT_HAIKU_MODEL the cheaper model is claude-haiku-4-5 on Anthropic's API; on Bedrock, Vertex or a custom ANTHROPIC_BASE_URL nothing switches until you list your models in NADIR_CLAUDE_MODELS. Needs a Claude Code build with hooks modules."
    }
  }
}
